SELECT CASE WHEN credit_limit >= 16400 THEN 'PREMIUM' ELSE 'STANDARD' END AS credit_limit_tier, DATE_TRUNC('WEEK', signup_date) AS week_start, COUNT_IF(country = 'DE') AS de_events, COUNT(DISTINCT city) AS distinct_cities, APPROX_PERCENTILE(age, ARRAY(0.25, 0.5, 0.75)) AS age_quartiles, STDDEV_SAMP(credit_limit) AS credit_limit_stddev, SUM(credit_limit) AS total_credit_limit FROM customers GROUP BY 1, 2 HAVING distinct_cities < 1 ORDER BY de_events
